// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {IRouterClient} from "@chainlink/contracts-ccip/contracts/interfaces/IRouterClient.sol";
import {Client} from "@chainlink/contracts-ccip/contracts/libraries/Client.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

contract TrigslinkCrossChain {
    IRouterClient public router;
    IERC20 public linkToken;
    mapping(uint64 => address) public destinationVaults;

    event CrossChainBetSent(
        bytes32 indexed messageId,
        uint64 indexed destinationChainSelector,
        string marketId,
        uint8 outcome,
        uint256 amount
    );

    constructor(address _router, address _linktoken) {
        router = IRouterClient(_router);
        linkToken = IERC20(_linktoken); 
    }

    function setDestinationVault (uint64 _chainselector, address _vault) external {
        destinationVaults[_chainselector] = _vault;
    }

    function placeCrossChainBet(
        uint64 _destinationChainSelector,
        string memory _marketId,
        uint8 _outcome,
        address _tokenToBet,
        uint256 _betAmount
    ) external returns (bytes32 messageId) {
        address targetVault = destinationVaults[_destinationChainSelector];
        require(targetVault != address(0), "Destination Vault not set");
        require(_outcome == 1 || _outcome == 2, "Invalid outcome" );

        IERC20(_tokenToBet).transferFrom(msg.sender, address(this), _betAmount);
        bytes memory payload = abi.encode(_marketId, _outcome, msg.sender);

        Client.EVMTokenAmount[] memory tokenAmounts = new Client.EVMTokenAmount[](1);
        tokenAmounts[0] = Client.EVMTokenAmount({token: _tokenToBet, amount: _betAmount});

        Client.EVM2AnyMessage memory evm2AnyMessage = Client.EVM2AnyMessage({
            receiver: abi.encode(targetVault),
            data: payload,
            tokenAmounts: tokenAmounts,
            extraArgs: Client._argsToBytes(Client.EVMExtraArgsV1({gasLimit: 400_000})),
            feeToken: address(linkToken)
        });

        uint256 fees = router.getFee(_destinationChainSelector, evm2AnyMessage);
        linkToken.transferFrom(msg.sender, address(this), fees);
        linkToken.approve(address(router), fees);
        IERC20(_tokenToBet).approve(address(router), _betAmount);

        messageId = router.ccipSend(_destinationChainSelector, evm2AnyMessage);
        emit CrossChainBetSent(messageId, _destinationChainSelector, _marketId, _outcome, _betAmount);
        return messageId;
    }
}

contracts/TrigslinkGovernance.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

// Interface to communicate with your existing TrigslinkVault
interface ITrigslinkVault {
    function createMarket(string calldata _marketId, string calldata _question, string calldata _dataSource) external;
}

contract TrigslinkGovernance is ReentrancyGuard {
    IERC20 public trigsToken; // Kept so token holders still control the voting
    ITrigslinkVault public vault;

    uint256 public proposalStakeRequired; // e.g., 0.01 ether (Native Gas)
    uint256 public votingPeriod;          // e.g., 24 hours
    address payable public treasury;      // Where slashed ETH goes

    uint256 public proposalCount;

    struct Proposal {
        uint256 id;
        string marketId;
        string question;
        string dataSource;
        address payable creator; // Must be payable to receive the ETH refund
        uint256 endTime;
        uint256 yesVotes;
        uint256 noVotes;
        bool executed;
        bool spam;
    }

    mapping(uint256 => Proposal) public proposals;
    mapping(uint256 => mapping(address => bool)) public hasVoted;

    event MarketProposed(uint256 indexed proposalId, string marketId, address indexed creator, string question, uint256 stakeAmount);
    event Voted(uint256 indexed proposalId, address indexed voter, bool support, uint256 weight);
    event MarketExecuted(uint256 indexed proposalId, string marketId, bool passed);

    constructor(address _trigsToken, address _vault, address payable _treasury, uint256 _stakeRequired) {
        trigsToken = IERC20(_trigsToken);
        vault = ITrigslinkVault(_vault);
        treasury = _treasury;
        proposalStakeRequired = _stakeRequired; // Set this to something like 0.01 ether
        votingPeriod = 24 hours; 
    }

    /**
     * @dev Step 1: User sends Native Gas (ETH/MATIC) to propose a new market.
     */
    function proposeMarket(string calldata _marketId, string calldata _question, string calldata _dataSource) external payable nonReentrant {
        // Enforce the exact Native Gas stake requirement
        require(msg.value == proposalStakeRequired, "Incorrect ETH stake amount sent");

        proposalCount++;

        proposals[proposalCount] = Proposal({
            id: proposalCount,
            marketId: _marketId,
            question: _question,
            dataSource: _dataSource,
            creator: payable(msg.sender), // Store as payable for the refund
            endTime: block.timestamp + votingPeriod,
            yesVotes: 0,
            noVotes: 0,
            executed: false,
            spam: false
        });

        emit MarketProposed(proposalCount, _marketId, msg.sender, _question, msg.value);
    }

    /**
     * @dev Step 2: Community votes YES or NO. Weight is based on their TRIGS token balance.
     */
    function vote(uint256 _proposalId, bool _support) external {
        Proposal storage proposal = proposals[_proposalId];

        require(block.timestamp < proposal.endTime, "Voting period has ended");
        require(!hasVoted[_proposalId][msg.sender], "You have already voted");

        // Voting power is determined by token holdings (1 token = 1 vote)
        uint256 voterWeight = trigsToken.balanceOf(msg.sender);
        require(voterWeight > 0, "No voting power. You must hold TRIGS.");

        if (_support) {
            proposal.yesVotes += voterWeight;
        } else {
            proposal.noVotes += voterWeight;
        }

        hasVoted[_proposalId][msg.sender] = true;

        emit Voted(_proposalId, msg.sender, _support, voterWeight);
    }

    /**
     * @dev Step 3: Tally votes. If passed, deploy market & refund ETH. If failed, send ETH to treasury.
     */
    function executeProposal(uint256 _proposalId) external nonReentrant {
        Proposal storage proposal = proposals[_proposalId];

        require(block.timestamp >= proposal.endTime, "Voting is still active");
        require(!proposal.executed, "Proposal already executed");

        proposal.executed = true;

        // Consensus logic: More YES votes than NO votes
        if (proposal.yesVotes > proposal.noVotes) {
            // Deploy the market to the main Vault!
            vault.createMarket(proposal.marketId, proposal.question, proposal.dataSource);

            // Refund the Native ETH stake back to the creator
            (bool success, ) = proposal.creator.call{value: proposalStakeRequired}("");
            require(success, "ETH Refund failed");

            emit MarketExecuted(_proposalId, proposal.marketId, true);
        } else {
            // The community rejected it. Slash the ETH and send to the protocol treasury.
            proposal.spam = true;

            (bool success, ) = treasury.call{value: proposalStakeRequired}("");
            require(success, "ETH Slashing transfer failed");

            emit MarketExecuted(_proposalId, proposal.marketId, false);
        }
    }
}

contracts/TrigslinkVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IReceiver {
    function onReport(bytes calldata metadata, bytes calldata report) external;
}

contract TrigslinkVault is IReceiver {

    address public chainlinkForwarder;

    struct Market {
        string marketId;
        bool resolved;
        uint8 finalOutcome;
        uint256 totalPool;
        uint256 outcome1Pool;
        uint256 outcome2Pool;
        string question;
        string dataSource;
    }

    mapping(string => Market) public markets;
    // Mapping: marketId => userAddress => outcome(1 or 2) => amountBet
    mapping(string => mapping(address => mapping(uint8 => uint256))) public userBets;


    event MarketCreated(string indexed marketId, string question, string dataSource);
    event BetPlaced(string indexed marketId, address indexed user, uint8 outcome, uint256 amount);

    // The critical event that wakes up offchain ai workflow
    event SettlementRequested(string indexed marketId, string question, string dataSource);
    event MarketResolved(string indexed marketId, uint8 outcome);
    event WinningsClaimed(string indexed marketId, address indexed user, uint256 payout);

    constructor(address _chainlinkForwarder){
        chainlinkForwarder = _chainlinkForwarder;
    }

    function createMarket(string memory _marketId, string memory _question, string memory _dataSource) external {
        require(bytes(markets[_marketId].marketId).length == 0, "Market Exists");
        markets[_marketId] = Market(_marketId, false, 0, 0, 0, 0, _question, _dataSource);
        emit MarketCreated(_marketId, _question, _dataSource);
    }

    function placeBet(string memory _marketId, uint8 _outcome) external payable {
        require(msg.value > 0, "Bet must be greater than 0");
        require(_outcome == 1 || _outcome == 2, "Invalid outcome. Use 1 or 2.");
        require(!markets[_marketId].resolved, "Market already settled");

        // THE FIX: Ensure the market was actually created first!
        // This guarantees the AI has a valid question to read during settlement.
        require(bytes(markets[_marketId].marketId).length != 0, "Market does not exist");

        markets[_marketId].totalPool += msg.value;

        if(_outcome == 1){
            markets[_marketId].outcome1Pool += msg.value;
        } else {
            markets[_marketId].outcome2Pool += msg.value;
        }

        userBets[_marketId][msg.sender][_outcome] += msg.value;

        emit BetPlaced(_marketId, msg.sender, _outcome, msg.value);
    }


    function requestSettlement(string memory _marketId) external{
        require(!markets[_marketId].resolved, "Market already settled");
        emit SettlementRequested(_marketId, markets[_marketId].question, markets[_marketId].dataSource);
    }


    function onReport(bytes calldata /* metadata */, bytes calldata report) external override {
        require(msg.sender == chainlinkForwarder, "Only Chainlink DON can resolve");

        //Decodes the data came from TS workflow
        (string memory marketId, uint8 outcome) = abi.decode(report, (string, uint8));

        require(!markets[marketId].resolved, "Market already settled");
        require(outcome == 1  || outcome == 2, "Invalid AI response");

        markets[marketId].resolved = true;
        markets[marketId].finalOutcome = outcome;

        emit MarketResolved(marketId, outcome);
    }


    function claimWinnings(string memory _marketId) external {
        require(markets[_marketId].resolved, "Markets not resolved yet");

        uint8 winningOutcome = markets[_marketId].finalOutcome;
        uint256 userBet = userBets[_marketId][msg.sender][winningOutcome];
        require(userBet > 0, "No winning bets to claim");

        userBets[_marketId][msg.sender][winningOutcome] = 0;

        uint256 winningPool = winningOutcome == 1 ? markets[_marketId].outcome1Pool : markets[_marketId].outcome2Pool;
        uint256 totalPool = markets[_marketId].totalPool;
        uint256 payout = (userBet * totalPool) / winningPool;

        (bool success, ) = payable(msg.sender).call{value: payout}("");
        require(success, "Transfer failed");
        emit WinningsClaimed(_marketId, msg.sender, payout);
    }
}

